import java.util.ArrayList;

public class ListDeduperTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        ArrayList<String> items = new ArrayList<>(java.util.List.of("b", "a", "b", "c", "a"));
        try {
            check("first occurrences kept in order", "[b, a, c]", String.valueOf(ListDeduper.withoutDuplicates(items)));
            check("input list unchanged", "[b, a, b, c, a]", items.toString());
            check("no duplicates present", "[x, y, z]",
                    String.valueOf(ListDeduper.withoutDuplicates(new ArrayList<>(java.util.List.of("x", "y", "z")))));
            check("all identical", "[same]",
                    String.valueOf(ListDeduper.withoutDuplicates(new ArrayList<>(java.util.List.of("same", "same", "same")))));
            check("empty list", "[]", String.valueOf(ListDeduper.withoutDuplicates(new ArrayList<>())));
            check("case sensitive", "[Ann, ann]",
                    String.valueOf(ListDeduper.withoutDuplicates(new ArrayList<>(java.util.List.of("Ann", "ann", "Ann")))));
        } catch (Exception e) {
            System.out.println("FAIL  unexpected exception: " + e);
            failures++;
        }

        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

